"""Editor menus, extension layouts, dependency navigation and visible Melody memory."""
import argparse,json,sys,tempfile,threading,time,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from backend.factory_extensions import install_factory
from playwright.sync_api import sync_playwright,expect

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,required=True);out=parser.parse_args().output;out.mkdir(parents=True,exist_ok=True);checks=[];errors=[]
    def passed(text):checks.append(text);print('PASS',text,flush=True)
    with tempfile.TemporaryDirectory(prefix='zenit-menu-') as tmp:
        root=Path(tmp);ws=root/'Aurora';ws.mkdir();(ws/'main.py').write_text('def greet(name):\n    return "Hello, " + name\n\nprint(greet("Aurora"))\n');(ws/'hello.c').write_text('#include <stdio.h>\nint main(void) { puts("Aurora"); return 0; }\n')
        app=Application(ROOT,ws,data_dir=root/'profile');app.workspace.trusted=True;app.features.studio.update({'onboarded':True,'displayName':'Alex'});app.features.prefs.update({'general.locale':'en','general.showWelcome':False,'appearance.motion':True,'updates.automatic':False,'security.confirmRoutineActions':False})
        install_factory(app.features.extensions,ROOT)
        for name in ['Aurora snippets','Orbit colors','Markdown notes','C helpers','ASM examples']:
            package=root/(name+'.vsix')
            with zipfile.ZipFile(package,'w') as archive:archive.writestr('extension/package.json',json.dumps({'name':name.lower().replace(' ','-'),'publisher':'ui-fixture','version':'1.0.0','displayName':name,'description':'Declared local UI fixture for verifying catalog layouts.','engines':{'vscode':'*'},'contributes':{}}))
            review=app.features.extensions.inspect_local(str(package));app.features.extensions.install(review['ticket'],True)
        server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
        try:
            with sync_playwright() as pw:
                browser=pw.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1500,'height':950})
                def inject(route):
                    response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get p(){return platformUI},get preview(){return previewUI},get ed(){return editor},openFile};')
                page.route('**/src/app.js',inject);page.on('pageerror',lambda e:errors.append(e.message));page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.ready');page.evaluate('__qa.openFile("main.py")')
                expect(page.locator('.melody-session-strip')).to_be_hidden();expect(page.locator('.melody-utilities')).to_be_hidden();expect(page.locator('#ai-actions .ai-action-card')).to_have_count(2);page.wait_for_function('document.querySelector(".composer-context>button").textContent.includes("main.py")');page.wait_for_function('document.querySelector(".melody-art").classList.contains("gpu-ready") || document.querySelector(".melody-art canvas").dataset.graphicsError',timeout=20000);page.screenshot(path=str(out/'melody-calm.png'));page.locator('#assistant-panel').screenshot(path=str(out/'melody-panel.png'));passed('Melody keeps the model selector in its title and secondary tools behind one control');page.evaluate('__qa.ed.view.focus()');page.keyboard.press('Shift+F10');expect(page.locator('.editor-context-menu')).to_be_visible();expect(page.locator('.editor-menu-search input')).to_be_focused();page.locator('.editor-context-menu').evaluate('(e)=>Promise.all(e.getAnimations().map(a=>a.finished.catch(()=>{})))');page.screenshot(path=str(out/'editor-menu.png'));passed('Shift F10 opens the themed menu with searchable real editor actions')
                page.get_by_role('menuitem',name='Run & Inspect').click();expect(page.locator('.editor-context-menu')).to_have_count(2);page.keyboard.press('ArrowLeft');expect(page.locator('.editor-context-menu')).to_have_count(1);page.keyboard.press('Escape');expect(page.locator('.editor-context-menu')).to_have_count(0);passed('Nested menus support keyboard entry, return and dismissal without losing the editor')
                page.evaluate('__qa.preview.contextMenu.open(__qa.ed.view,1490,940)');boxes=page.locator('.editor-context-menu').evaluate_all('(nodes)=>nodes.map(n=>{const r=n.getBoundingClientRect();return {right:r.right,bottom:r.bottom,left:r.left,top:r.top}})');assert all(x['right']<=1500 and x['bottom']<=950 and x['left']>=0 for x in boxes);page.locator('.editor-menu-search input').fill('dependencies');expect(page.get_by_role('menuitem')).to_have_count(1);page.get_by_role('menuitem').click();expect(page.locator('.python-packages')).to_be_visible();passed('The menu stays in the viewport and searches directly into Python dependencies')
                page.locator('[data-extension-mode=native]').click();expect(page.locator('.native-packages')).to_be_visible();page.locator('[data-native-language=nc]').click();expect(page.locator('#native-requirement')).to_have_attribute('placeholder','stoud::io');page.locator('[data-native-language=asm]').click();expect(page.locator('.native-tools')).to_contain_text('nasm');passed('Extensions provides language-specific dependency controls for Python, C, C++, nC and ASM')
                page.locator('[data-extension-mode=installed]').click();page.wait_for_selector('.extension-card');page.locator('[data-extension-view=cards]').click();expect(page.locator('#extension-results')).to_have_attribute('data-view','cards');page.wait_for_function('!document.querySelector(".extension-card").getAnimations().length');page.screenshot(path=str(out/'extensions-cards.png'));page.locator('[data-extension-view=compact]').click();page.locator('[data-extension-view=list]').click();page.screenshot(path=str(out/'extensions-list.png'));page.locator('[data-extension-view=compact]').click();page.wait_for_function('!document.querySelector(".extension-card").getAnimations().length');page.screenshot(path=str(out/'extensions-compact.png'));passed('List, cards and compact layouts animate and tolerate rapid reversals')
                page.evaluate('__qa.p.extensions("installed")');page.wait_for_selector('.extension-card');expect(page.locator('#extension-results')).to_have_attribute('data-view','compact');page.emulate_media(reduced_motion='reduce');page.locator('[data-extension-view=cards]').click();assert page.evaluate('[...document.querySelectorAll(".extension-card")].every(e=>!e.getAnimations().length)');passed('The view choice persists across catalog refresh and respects reduced motion')
                page.evaluate('__qa.p.closePage()');page.locator('.melody-utilities-toggle').click();page.locator('[data-utility-tab=context]').click();expect(page.locator('.melody-memory-controls')).to_contain_text('Remember this file');expect(page.locator('.melody-memory-controls')).to_contain_text('0 exchanges');page.screenshot(path=str(out/'melody-memory.png'));page.locator('.melody-memory-controls input').uncheck();assert page.evaluate('__qa.p.melodyMemoryEnabled') is False;page.locator('.melody-memory-controls input').check();page.locator('.melody-memory-controls button').click();page.locator('[data-utilities-close]').click();passed('Melody exposes local file memory with pause and forget controls')
                page.evaluate('__qa.preview.contextMenu.open(__qa.ed.view,600,250)');page.get_by_role('menuitem',name='Melody',exact=True).click();page.get_by_role('menuitem',name='Explain Selection or File',exact=True).click();expect(page.locator('#ai-input')).to_have_value('Explain the attached code and its control flow.');passed('The Melody submenu opens the floating assistant with the requested action ready')
                browser.close()
        finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown();time.sleep(.4)
    data={'checks':checks,'errors':errors};(out/'verification.json').write_text(json.dumps(data,indent=2),encoding='utf-8');print(json.dumps(data))
    if errors:raise AssertionError(errors)
if __name__=='__main__':main()
